#include <string>
#include <utility>
#include <vector>
struct Item {
    std::string name;
    explicit Item(std::string s) : name(std::move(s)) {}
};
int main() {
    std::vector<Item> items;
    items.reserve(2);
    // 이렇게 쓰기 쉽다: 임시 Item 1개를 만든 뒤 이동
    items.push_back(Item{"책"});
    // 이렇게 고친다: Item을 저장 공간에 바로 생성
    items.emplace_back("연필");
}
```

